mapper.select:
SELECT s.SCHEDULE_NO AS scheduleNo , r.REQUEST_NO AS requestNo , r.STATUS AS requestStatus , s.START_TIME AS startTime , s.END_TIME AS endTime , r.CUSTOMER_NAME AS customerName , r.SYMPTOM AS symptom FROM AS_SCHEDULE s
JOIN REQUEST r ON s.REQUEST_NO = r.REQUEST_NO
JOIN ENGINEER e ON s.ENGINEER_NO = e.ENGINEER_NO WHERE e.MEM_NO = #{memNo} AND DATE(s.START_TIME) = CURDATE() ORDER BY s.START_TIME;

SELECT COUNT(*)
FROM AS_SCHEDULE s
JOIN ENGINEER e ON s.ENGINEER_NO = e.ENGINEER_NO
WHERE s.SCHEDULE_NO = #{scheduleNo}
AND e.MEM_NO = #{memNo};

mapper.update:
UPDATE REQUEST
SET STATUS = 'COMPLETED'
WHERE REQUEST_NO = #{requestNo};

mapper.select:
SELECT CUSTOMER_TEL
FROM REQUEST
WHERE REQUEST_NO = #{requestNo};

SELECT ENGINEER_NO
FROM ENGINEER
WHERE MEM_NO = #{memNo};

mapper.insert:
INSERT INTO AS_RESULT (
SCHEDULE_NO
, PROCESS_DATE
, PROCESS_CONTENT
, IMAGE_PATH
, IMAGE_PATH2
, NO_PHOTO_REASON
)
VALUES (
#{scheduleNo}
, #{processDate}
, #{processContent}
, #{imagePath}
, #{imagePath2}
, #{noPhotoReason});

mapper.update:
UPDATE AS_RESULT
SET PROCESS_CONTENT = #{processContent}
, IMAGE_PATH = #{imagePath}
, IMAGE_PATH2 = #{imagePath2}
, NO_PHOTO_REASON = #{noPhotoReason}
, UPDATED_AT = #{updatedAt}
WHERE SCHEDULE_NO = #{scheduleNo}
